import React from "react";

import UIStore from "../../../stores/UIStore";
import AccessibleButton from "../elements/AccessibleButton";
import { ContextMenuButton, useContextMenu } from "../../structures/ContextMenu";
import IconizedContextMenu, { IconizedContextMenuOptionList } from "./IconizedContextMenu";

interface IProps extends Omit<React.ComponentProps<typeof AccessibleButton>, "onClick"> {
    options: React.ReactNode[];
    title: string;
}

export const KebabContextMenu: React.FC<IProps> = ({ options, title, disabled, ...props }) => {
    const [isOpen, buttonRef, open, close] = useContextMenu<HTMLDivElement>();
    const rect = buttonRef.current?.getBoundingClientRect();
    const menuOptions = options.map((option) => React.isValidElement(option)
        ? React.cloneElement(option as React.ReactElement<{ onClick?: (ev: React.SyntheticEvent) => void }>, {
            onClick: (ev: React.SyntheticEvent) => {
                option.props.onClick?.(ev);
                close();
                ev.stopPropagation();
            },
        }) : option);

    return <>
        <ContextMenuButton
            {...props}
            inputRef={buttonRef}
            className="mx_KebabContextMenu_button"
            label={title}
            isExpanded={isOpen}
            disabled={disabled}
            aria-disabled={disabled}
            onClick={open}
        >
            <span className="mx_KebabContextMenu_icon" aria-hidden="true" />
        </ContextMenuButton>
        { isOpen && rect && <IconizedContextMenu
            top={rect.bottom + window.scrollY}
            right={UIStore.instance.windowWidth - rect.right - window.scrollX}
            rightAligned
            onFinished={close}
        >
            <IconizedContextMenuOptionList red>{ menuOptions }</IconizedContextMenuOptionList>
        </IconizedContextMenu> }
    </>;
};
